/* ===========================================================
   LA ESPADA CELESTIAL — motor de juego
   Estado, colisiones, combate, IA, misiones y progresión.
   =========================================================== */
'use strict';

const SAVE_KEY = 'la-espada-celestial:v1';

const game = {
  scene: 'title',            // title | play | dialog | panel | death | ending | travel
  mapId: 'village',
  map: null,
  p: null,
  enemies: [],
  boss: null,
  projectiles: [],
  particles: [],
  numbers: [],
  effects: [],
  weather: [],
  camera: { x: 0, y: 0 },
  view: { w: 400, h: 700, zoom: 1, dpr: 1 },
  time: 0,
  shake: 0,
  portalCd: 0,
  interact: null,
  transition: false,
  endingTimer: 0,
  saveTimer: 0,
  shrineCd: 0,
  travelMessage: 0
};

/* ----------------------------- Jugador ----------------------------- */
function newPlayer() {
  return {
    x: 750, y: 840, r: 12, dir: -Math.PI / 2, speed: 172,
    hp: 100, maxHp: 100, mp: 50, maxMp: 50,
    level: 1, xp: 0, xpNext: 50, gold: 0, atk: 12,
    potions: 3, ethers: 1, blade: 0,
    atkCd: 0, skillCd: 0, healCd: 0, invuln: 0, atkAnim: 0, hitFlash: 0,
    stage: 1, slimeKills: 0, ghostKills: 0,
    kills: 0, playTime: 0
  };
}

function bladeName() {
  return ['Hoja de aprendiz', 'Espada de plata', 'Espada lunar', 'Espada Celestial'][game.p.blade] || 'Espada Celestial';
}
function bladeColor() {
  return ['#cfd6e2', '#e8eef8', '#a8dcff', '#ffe39a'][game.p.blade] || '#ffe39a';
}

/* ----------------------------- Mapas ----------------------------- */
function loadMap(id, pos) {
  const map = (MAP_BUILDERS[id] || MAP_BUILDERS.village)();
  const p = game.p;
  game.mapId = id;
  game.map = map;
  game.enemies = [];
  game.boss = null;

  for (const def of map.enemies) {
    const base = ENEMY_DEFS[def.type];
    if (def.type === 'boss') {
      if (p.stage !== 4) continue;
      game.boss = {
        type: 'boss', name: base.name, x: def.x, y: def.y, r: base.r,
        hp: base.hp, maxHp: base.hp, speed: base.speed, dmg: base.dmg,
        xp: base.xp, gold: base.gold, aggro: base.aggro,
        active: false, dead: false, state: 'chase', timer: 0, atkCd: 1.4,
        phase: 1, dir: Math.PI / 2, hitFlash: 0, kx: 0, ky: 0,
        slamX: 0, slamY: 0, slamR: 0, volleyCd: 3
      };
      continue;
    }
    game.enemies.push({
      type: def.type, name: base.name, x: def.x, y: def.y, home: def.home,
      r: base.r, hp: base.hp, maxHp: base.hp, speed: base.speed, dmg: base.dmg,
      xp: base.xp, gold: base.gold, aggro: base.aggro,
      state: 'idle', timer: 0, atkCd: rand(0.3, 1.2), shootCd: rand(1.5, 3),
      dir: Math.PI / 2, hitFlash: 0, kx: 0, ky: 0, wander: 0, wx: 0, wy: 0,
      dead: false
    });
  }

  if (map.chest) map.chest.opened = p.stage >= 4;

  const start = pos || map.spawn;
  p.x = clamp(start.x, 30, map.w - 30);
  p.y = clamp(start.y, 30, map.h - 30);
  p.atkAnim = 0;
  p.invuln = Math.max(p.invuln, 0.6);

  game.projectiles = [];
  game.particles = [];
  game.numbers = [];
  game.effects = [];
  game.portalCd = 1.1;
  game.interact = null;
  initWeather(map);
  snapCamera();
  hideBossBar();
  updateHUD();
}

function initWeather(map) {
  const rng = mulberry32(map._seed * 977 + 13);
  const n = map.ambient === 'leaves' ? 42 : map.ambient === 'embers' ? 46 : 26;
  game.weather = [];
  for (let i = 0; i < n; i++) {
    game.weather.push({
      x: rng() * map.w, y: rng() * map.h,
      vx: map.ambient === 'leaves' ? 14 + rng() * 20 : (rng() - 0.5) * 10,
      vy: map.ambient === 'embers' ? -14 - rng() * 24 : 8 + rng() * 14,
      s: 1.4 + rng() * 2.4, ph: rng() * Math.PI * 2,
      kind: map.ambient
    });
  }
}

/* ----------------------------- Guardado ----------------------------- */
function saveGame(silent) {
  if (!game.p) return;
  try {
    const payload = { v: 1, mapId: game.mapId, p: game.p, at: Date.now() };
    localStorage.setItem(SAVE_KEY, JSON.stringify(payload));
    if (!silent) toast('Partida guardada', 'gold');
  } catch (e) {
    if (!silent) toast('No se pudo guardar', 'danger');
  }
}

function hasSave() {
  try { return !!localStorage.getItem(SAVE_KEY); } catch (e) { return false; }
}

function loadGame() {
  let data = null;
  try { data = JSON.parse(localStorage.getItem(SAVE_KEY) || 'null'); } catch (e) { data = null; }
  if (!data || !data.p) { toast('No hay partida guardada', 'danger'); return false; }
  const p = Object.assign(newPlayer(), data.p);
  p.stage = clamp(Math.round(p.stage || 1), 1, 5);
  p.level = Math.max(1, Math.round(p.level));
  p.maxHp = Math.max(100, p.maxHp);
  p.maxMp = Math.max(50, p.maxMp);
  p.hp = clamp(p.hp, 1, p.maxHp);
  p.mp = clamp(p.mp, 0, p.maxMp);
  p.xpNext = Math.max(10, p.xpNext);
  p.potions = Math.max(0, p.potions | 0);
  p.ethers = Math.max(0, p.ethers | 0);
  p.blade = clamp(p.blade | 0, 0, 3);
  game.p = p;
  game.scene = 'play';
  loadMap(data.mapId && MAP_BUILDERS[data.mapId] ? data.mapId : 'village', { x: p.x, y: p.y });
  hideTitle();
  document.body.classList.toggle('low-hp', false);
  toast('Partida cargada', 'gold');
  return true;
}

/* ----------------------------- Movimiento y colisión ----------------------------- */
function collide(ent, map) {
  const r = ent.r;
  for (const o of map.obstacles) {
    if (o.t === 'r') {
      const nx = clamp(ent.x, o.x, o.x + o.w);
      const ny = clamp(ent.y, o.y, o.y + o.h);
      let dx = ent.x - nx, dy = ent.y - ny;
      let d2 = dx * dx + dy * dy;
      if (d2 < r * r) {
        if (d2 > 0.0001) {
          const d = Math.sqrt(d2);
          ent.x += (dx / d) * (r - d);
          ent.y += (dy / d) * (r - d);
        } else {
          const left = ent.x - o.x, right = o.x + o.w - ent.x;
          const top = ent.y - o.y, bottom = o.y + o.h - ent.y;
          const m = Math.min(left, right, top, bottom);
          if (m === left) ent.x = o.x - r;
          else if (m === right) ent.x = o.x + o.w + r;
          else if (m === top) ent.y = o.y - r;
          else ent.y = o.y + o.h + r;
        }
      }
    } else if (o.t === 'c') {
      const dx = ent.x - o.x, dy = ent.y - o.y;
      const rr = r + o.r;
      const d2 = dx * dx + dy * dy;
      if (d2 < rr * rr) {
        const d = Math.sqrt(d2) || 0.001;
        ent.x = o.x + (dx / d) * rr;
        ent.y = o.y + (dy / d) * rr;
      }
    }
  }
  ent.x = clamp(ent.x, 26, map.w - 26);
  ent.y = clamp(ent.y, 34, map.h - 26);
}

function moveEntity(ent, dx, dy, map) {
  ent.x += dx;
  ent.y += dy;
  collide(ent, map);
}

/* ----------------------------- Partículas y números ----------------------------- */
function burst(x, y, color, n = 8, speed = 110, size = 3) {
  for (let i = 0; i < n; i++) {
    const a = rand(0, Math.PI * 2);
    const sp = rand(speed * 0.3, speed);
    game.particles.push({
      x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp - 20,
      life: rand(0.25, 0.6), max: 0.6, size: rand(size * 0.6, size), color, grav: 120
    });
  }
}

function addNumber(x, y, text, color = '#fff', crit = false) {
  game.numbers.push({ x: x + rand(-6, 6), y, text, color, crit, life: 0.85, max: 0.85, vy: -52 });
}

function addRing(x, y, r, color, life = 0.5) {
  game.effects.push({ kind: 'ring', x, y, r, color, life, max: life });
}

/* ----------------------------- Combate ----------------------------- */
function nearestEnemy(maxDist) {
  let best = null, bd = maxDist * maxDist;
  const list = game.boss && !game.boss.dead ? [...game.enemies, game.boss] : game.enemies;
  for (const e of list) {
    if (e.dead) continue;
    const d = dist2(game.p.x, game.p.y, e.x, e.y);
    if (d < bd) { bd = d; best = e; }
  }
  return best;
}

function playerAttack() {
  const p = game.p;
  if (game.scene !== 'play' || p.atkCd > 0) return;
  p.atkCd = 0.4;
  p.atkAnim = 0.2;

  const aim = nearestEnemy(160);
  if (aim) p.dir = Math.atan2(aim.y - p.y, aim.x - p.x);

  AudioFX.swing();
  game.effects.push({ kind: 'slash', x: p.x, y: p.y, dir: p.dir, life: 0.2, max: 0.2 });

  const targets = game.boss && !game.boss.dead ? [...game.enemies, game.boss] : game.enemies;
  for (const e of targets) {
    if (e.dead) continue;
    const d = dist(p.x, p.y, e.x, e.y);
    if (d > 70 + e.r) continue;
    const a = Math.atan2(e.y - p.y, e.x - p.x);
    if (angleDiff(a, p.dir) > 1.05) continue;
    const crit = Math.random() < 0.15;
    const dmg = Math.round(p.atk * rand(0.9, 1.12) * (crit ? 1.9 : 1));
    damageEnemy(e, dmg, crit, a);
  }
}

function playerSkill() {
  const p = game.p;
  if (game.scene !== 'play' || p.skillCd > 0) return;
  if (p.mp < 12) { toast('No tienes suficiente maná', 'danger'); return; }
  p.mp -= 12;
  p.skillCd = 2.6;
  AudioFX.tone(300, 0.5, 'triangle', 0.06, 500);
  addRing(p.x, p.y, 110, '#9fdcff', 0.5);
  addRing(p.x, p.y, 70, '#ffe9b0', 0.4);
  burst(p.x, p.y, '#bfe9ff', 26, 240, 4);

  const targets = game.boss && !game.boss.dead ? [...game.enemies, game.boss] : game.enemies;
  for (const e of targets) {
    if (e.dead) continue;
    if (dist(p.x, p.y, e.x, e.y) > 112 + e.r) continue;
    damageEnemy(e, Math.round(p.atk * 1.7), false, Math.atan2(e.y - p.y, e.x - p.x), 14);
  }
}

function playerHeal() {
  const p = game.p;
  if (game.scene !== 'play' || p.healCd > 0) return;
  if (p.mp < 20) { toast('No tienes suficiente maná', 'danger'); return; }
  if (p.hp >= p.maxHp) { toast('Tu vida ya está completa'); return; }
  p.mp -= 20;
  p.healCd = 8;
  const amount = Math.round(p.maxHp * 0.35);
  p.hp = Math.min(p.maxHp, p.hp + amount);
  addNumber(p.x, p.y - 26, `+${amount}`, '#8ff0a8');
  burst(p.x, p.y, '#8ff0a8', 18, 90, 3);
  AudioFX.heal();
  updateHUD();
}

function usePotion() {
  const p = game.p;
  if (game.scene !== 'play') return;
  if (p.potions <= 0) { toast('No te quedan pociones', 'danger'); return; }
  if (p.hp >= p.maxHp) { toast('Tu vida ya está completa'); return; }
  p.potions--;
  const amount = 45;
  p.hp = Math.min(p.maxHp, p.hp + amount);
  addNumber(p.x, p.y - 26, `+${amount}`, '#ff9ab8');
  burst(p.x, p.y, '#ff9ab8', 14, 80, 3);
  AudioFX.pickup();
  updateHUD();
}

function useEther() {
  const p = game.p;
  if (game.scene !== 'play') return;
  if (p.ethers <= 0) return;
  if (p.mp >= p.maxMp) { toast('Tu maná ya está completo'); return; }
  p.ethers--;
  p.mp = Math.min(p.maxMp, p.mp + 32);
  addNumber(p.x, p.y - 26, '+32', '#9fd8ff');
  AudioFX.pickup();
  updateHUD();
}

function damageEnemy(e, dmg, crit, angle, knock = 9) {
  if (e.dead) return;
  e.hp -= dmg;
  e.hitFlash = 0.13;
  if (e.kx !== undefined) {
    e.kx += Math.cos(angle) * knock * 6;
    e.ky += Math.sin(angle) * knock * 6;
  }
  addNumber(e.x, e.y - e.r - 8, String(dmg), crit ? '#ffd76a' : '#fff2dc', crit);
  burst(e.x, e.y - e.r * 0.4, crit ? '#ffd76a' : '#ffd9b0', crit ? 12 : 6, crit ? 170 : 110, crit ? 4 : 3);
  AudioFX.hit();
  if (e === game.boss) updateBossBar();
  if (e.hp <= 0) {
    e.hp = 0;
    e.dead = true;
    onEnemyKilled(e);
  }
}

function damagePlayer(dmg) {
  const p = game.p;
  if (game.scene !== 'play' || p.invuln > 0) return;
  p.hp -= dmg;
  p.invuln = 0.62;
  p.hitFlash = 0.22;
  game.shake = Math.max(game.shake, 9);
  addNumber(p.x, p.y - 30, `-${dmg}`, '#ff7b7b');
  burst(p.x, p.y, '#ff6f6f', 10, 120, 3);
  AudioFX.hurt();
  updateHUD();
  if (p.hp <= 0) {
    p.hp = 0;
    die();
  }
}

function onEnemyKilled(e) {
  const p = game.p;
  p.kills++;
  p.gold += e.gold || 0;
  gainXP(e.xp || 0);
  burst(e.x, e.y - e.r * 0.5, e.type === 'ghost' ? '#cfe6ff' : '#a9e08a', 22, 180, 4);
  addRing(e.x, e.y, e.r + 20, e.type === 'ghost' ? '#cfe6ff' : '#a9e08a', 0.4);

  if (e.type === 'slime' && p.stage === 2) {
    p.slimeKills = Math.min(5, p.slimeKills + 1);
    toast(`Limos derrotados ${p.slimeKills}/5`, 'quest');
    if (p.slimeKills >= 5) {
      p.stage = 3;
      p.gold += 40;
      toast('¡Misión completada! El camino a las Ruinas se ha abierto', 'gold');
      addRing(p.x, p.y, 90, '#ffe39a', 0.8);
      AudioFX.level();
      saveGame(true);
    }
    updateHUD();
  }

  if (e.type === 'ghost' && p.stage === 3) {
    p.ghostKills = Math.min(6, p.ghostKills + 1);
    toast(`Espectros derrotados ${p.ghostKills}/6`, 'quest');
    if (p.ghostKills >= 6) {
      toast('El Fragmento de Ceniza se manifiesta en el centro de las Ruinas', 'gold');
      addRing(p.x, p.y, 110, '#ffd08a', 0.9);
      AudioFX.level();
      saveGame(true);
    }
    updateHUD();
  }

  if (e === game.boss) {
    onBossDefeated();
    return;
  }

  if (Math.random() < 0.18) {
    p.potions++;
    addNumber(e.x, e.y - 34, '+1 🧪', '#ffa8d8');
  }
  saveGame(true);
}

function gainXP(amount) {
  const p = game.p;
  p.xp += amount;
  let leveled = false;
  while (p.xp >= p.xpNext) {
    p.xp -= p.xpNext;
    p.level++;
    p.xpNext = Math.round(p.xpNext * 1.45);
    p.maxHp += 18;
    p.maxMp += 8;
    p.atk += 3;
    p.hp = p.maxHp;
    p.mp = p.maxMp;
    leveled = true;
  }
  if (leveled) {
    addRing(p.x, p.y, 100, '#ffe39a', 0.8);
    burst(p.x, p.y, '#ffe39a', 30, 200, 4);
    toast(`¡Nivel ${p.level}! Vida y poder restaurados`, 'gold');
    AudioFX.level();
    saveGame(true);
  }
  updateHUD();
}

function onBossDefeated() {
  const p = game.p;
  game.boss.dead = true;
  game.shake = 22;
  burst(game.boss.x, game.boss.y, '#ffb36a', 60, 300, 5);
  addRing(game.boss.x, game.boss.y, 190, '#ffe39a', 1.2);
  hideBossBar();
  p.stage = 5;
  p.gold += 260;
  toast('El Señor de la Ceniza ha caído. La espada despierta.', 'gold');
  AudioFX.level();
  saveGame(true);
  game.endingTimer = 2.8;
  updateHUD();
}

/* ----------------------------- Muerte ----------------------------- */
function die() {
  game.scene = 'death';
  AudioFX.tone(140, 1, 'sawtooth', 0.06, -90);
  showDeath();
}

function retry() {
  const p = game.p;
  p.hp = Math.max(1, Math.round(p.maxHp * 0.6));
  p.mp = Math.max(10, Math.round(p.maxMp * 0.5));
  p.gold = Math.floor(p.gold * 0.9);
  p.invuln = 2;
  game.scene = 'play';
  hideDeath();
  loadMap(game.mapId, game.map.spawn);
  toast('Te levantas, pero la ceniza se llevó parte de tu oro', 'danger');
  saveGame(true);
}

/* ----------------------------- Misiones ----------------------------- */
function questTarget() {
  const p = game.p;
  if (p.stage === 1) return { mapId: 'village', x: 618, y: 664 };
  if (p.stage === 2) {
    if (game.mapId === 'forest') {
      const s = game.enemies.find((e) => e.type === 'slime' && !e.dead);
      return s ? { mapId: 'forest', x: s.x, y: s.y } : { mapId: 'forest', x: 800, y: 640 };
    }
    return game.mapId === 'village' ? { mapId: 'village', x: 750, y: 108 } : { mapId: 'forest', x: 800, y: 1070 };
  }
  if (p.stage === 3) {
    if (game.mapId === 'ruins') {
      if (p.ghostKills >= 6) return { mapId: 'ruins', x: 800, y: 780 };
      const g = game.enemies.find((e) => e.type === 'ghost' && !e.dead);
      return g ? { mapId: 'ruins', x: g.x, y: g.y } : { mapId: 'ruins', x: 800, y: 640 };
    }
    if (game.mapId === 'forest') return { mapId: 'forest', x: 1548, y: 640 };
    return { mapId: 'village', x: 750, y: 108 };
  }
  if (p.stage === 4) {
    if (game.mapId === 'temple' && game.boss && !game.boss.dead) {
      return { mapId: 'temple', x: game.boss.x, y: game.boss.y };
    }
    if (game.mapId === 'ruins') return { mapId: 'ruins', x: 800, y: 90 };
    if (game.mapId === 'forest') return { mapId: 'forest', x: 1548, y: 640 };
    return { mapId: 'village', x: 750, y: 108 };
  }
  return null;
}

function questProgressText() {
  const p = game.p;
  if (p.stage === 2) return `${p.slimeKills}/5 limos`;
  if (p.stage === 3) return p.ghostKills >= 6 ? 'Reclama el fragmento' : `${p.ghostKills}/6 espectros`;
  return '';
}

/* ----------------------------- Interacción ----------------------------- */
function findInteract() {
  const p = game.p;
  const map = game.map;
  let best = null, bd = Infinity;
  for (const npc of map.npcs) {
    const d = dist(p.x, p.y, npc.x, npc.y);
    if (d < 80 && d < bd) { bd = d; best = { type: 'npc', ref: npc, label: 'Hablar', x: npc.x, y: npc.y }; }
  }
  if (map.chest) {
    const c = map.chest;
    const d = dist(p.x, p.y, c.x, c.y);
    if (d < 80) {
      if (!c.opened && p.stage === 3 && p.ghostKills >= 6) {
        if (d < bd) { bd = d; best = { type: 'chest', ref: c, label: 'Abrir', x: c.x, y: c.y }; }
      } else if (!c.opened && p.stage < 4 && d < bd) {
        bd = d; best = { type: 'chestLocked', ref: c, label: 'Examinar', x: c.x, y: c.y };
      }
    }
  }
  if (map.shrine) {
    const d = dist(p.x, p.y, map.shrine.x, map.shrine.y);
    if (d < 95 && d < bd) { bd = d; best = { type: 'shrine', ref: map.shrine, label: 'Rezar', x: map.shrine.x, y: map.shrine.y }; }
  }
  return best;
}

function doInteract() {
  if (game.scene !== 'play' || !game.interact) return;
  const it = game.interact;
  if (it.type === 'npc') talkTo(it.ref);
  else if (it.type === 'chest') openChest();
  else if (it.type === 'chestLocked') openDialog({
    who: 'Cofre sellado', text: 'La ceniza aún no se ha calmado. Algo duerme aquí, esperando a que las ruinas callen.',
    options: [{ label: 'Retirarse', cb: closeDialog }]
  });
  else if (it.type === 'shrine') useShrine();
}

function useShrine() {
  const p = game.p;
  if (game.shrineCd > 0) { toast('La bendición aún se está recuperando', 'danger'); return; }
  if (p.hp >= p.maxHp && p.mp >= p.maxMp) { toast('Ya estás pleno de vida y maná'); return; }
  p.hp = p.maxHp;
  p.mp = p.maxMp;
  game.shrineCd = 25;
  addRing(p.x, p.y, 120, '#9fdcff', 0.9);
  burst(p.x, p.y, '#9fdcff', 26, 150, 4);
  AudioFX.heal();
  toast('La bendición lunar restaura tu vida y tu maná', 'quest');
  updateHUD();
}

function openChest() {
  const p = game.p;
  const c = game.map.chest;
  if (!c || c.opened) return;
  c.opened = true;
  p.ghostKills = 6;
  p.stage = 4;
  p.gold += 120;
  p.potions += 2;
  addRing(c.x, c.y, 150, '#ffe39a', 1.1);
  burst(c.x, c.y, '#ffe39a', 40, 220, 5);
  AudioFX.chest();
  openDialog({
    who: 'Fragmento de Ceniza',
    text: 'El fragmento flota sobre el cofre y se funde con la hoja. La espada recuerda su nombre: Celestial. Pero su luz aún está incompleta… el Señor de la Ceniza aguarda en el Templo.',
    options: [{ label: 'Alzar la espada', cb: () => { closeDialog(); p.blade = Math.max(p.blade, 2); toast('La Espada lunar despierta · +4 ataque', 'gold'); p.atk += 4; updateHUD(); saveGame(true); } }]
  });
}

/* ----------------------------- Diálogos de NPC ----------------------------- */
function talkTo(npc) {
  const p = game.p;
  if (npc.id === 'mira') {
    if (p.stage === 1) {
      openDialog({
        who: 'Anciana Mira',
        text: 'La ceniza ha cubierto el Bosque y algo antiguo se mueve en las Ruinas. Portas la hoja que soñó con el cielo, muchacho. Ve al Bosque Susurrante y derrota a los limos que corrompen la senda. Así empezarás a despertar su filo.',
        options: [{
          label: 'Aceptar el llamado', cb: () => {
            closeDialog();
            p.stage = 2;
            p.potions += 1;
            toast('Nueva misión: Limo y ceniza', 'quest');
            addRing(p.x, p.y, 80, '#ffe39a', 0.7);
            AudioFX.level();
            updateHUD();
            saveGame(true);
          }
        }, { label: 'Todavía no', cb: closeDialog }]
      });
    } else if (p.stage === 2) {
      openDialog({
        who: 'Anciana Mira',
        text: `La senda del bosque está al norte. Los limos han bebido de la ceniza: ${p.slimeKills} de 5 han caído. Cuando termines, las Ruinas te abrirán su puerta.`,
        options: [{ label: 'Entendido', cb: closeDialog }]
      });
    } else if (p.stage === 3) {
      openDialog({
        who: 'Anciana Mira',
        text: `Las Ruinas guardan el Fragmento. Los espectros lo custodian: ${p.ghostKills} de 6 han vuelto al polvo. No toques el fragmento con miedo, o la ceniza te reclamará.`,
        options: [{ label: 'Seguir adelante', cb: closeDialog }]
      });
    } else if (p.stage === 4) {
      openDialog({
        who: 'Anciana Mira',
        text: 'El Templo Celestial se alza tras las Ruinas. El Señor de la Ceniza fue un rey que quiso robar la luz de la espada. Tu hoja ya recuerda su nombre. Termina lo que empezó hace mil años.',
        options: [{ label: 'Iré al Templo', cb: closeDialog }]
      });
    } else {
      openDialog({
        who: 'Anciana Mira',
        text: 'El cielo vuelve a verse sobre la aldea. La espada canta en tu mano, y los niños ya no temen a la noche. Descansa, héroe: el reino recordará tu nombre.',
        options: [{ label: 'Despedirse', cb: closeDialog }]
      });
    }
    return;
  }

  if (npc.id === 'herrero') {
    const options = [];
    if (p.blade < 3) {
      options.push({
        label: `Mejorar espada · 60 ◈`, cb: () => {
          if (p.gold < 60) { toast('Necesitas 60 de oro', 'danger'); return; }
          p.gold -= 60;
          p.blade++;
          p.atk += 4;
          toast(`${bladeName()} forjada · +4 ataque`, 'gold');
          AudioFX.level();
          updateHUD();
          saveGame(true);
          closeDialog();
        }
      });
    }
    options.push({
      label: 'Comprar poción · 25 ◈', cb: () => {
        if (p.gold < 25) { toast('Necesitas 25 de oro', 'danger'); return; }
        p.gold -= 25;
        p.potions++;
        toast('Poción comprada', 'gold');
        AudioFX.pickup();
        updateHUD();
        saveGame(true);
        closeDialog();
      }
    });
    options.push({ label: 'Despedirse', cb: closeDialog });
    openDialog({
      who: 'Herrero Bruno',
      text: p.blade < 3
        ? `Tu hoja tiene sed de ceniza. Puedo reforzarla con plata lunar (${bladeName()} · nivel ${p.blade + 1}/3), pero el metal cuesta 60 de oro. También vendo pociones a 25.`
        : 'Tu espada ya es una leyenda. No hay yunque en este reino que pueda mejorarla más.',
      options
    });
  }
}

/* ----------------------------- Viaje ----------------------------- */
function tryPortal(portal) {
  if (game.transition) return;
  const p = game.p;
  if (portal.needStage && p.stage < portal.needStage) {
    const msg = portal.to === 'ruins'
      ? 'El sendero está sellado por la ceniza. Derrota a los 5 limos primero.'
      : 'El Templo está sellado. Recupera el Fragmento de Ceniza en las Ruinas.';
    toast(msg, 'danger');
    addRing(portal.x, portal.y, 46, '#ff7b7b', 0.4);
    game.portalCd = 1.6;
    return;
  }
  game.transition = true;
  game.scene = 'travel';
  $('fader').classList.add('on');
  AudioFX.portal();
  setTimeout(() => {
    loadMap(portal.to, portal.spawn);
    game.scene = 'play';
    game.transition = false;
    $('fader').classList.remove('on');
    toast(ZONE_NAMES[game.mapId] || '', 'quest');
    saveGame(true);
  }, 380);
}

/* ----------------------------- Cámara ----------------------------- */
function updateCamera(dt) {
  const v = game.view;
  const map = game.map;
  const p = game.p;
  let tx = p.x - v.w / 2;
  let ty = p.y - v.h / 2;
  if (map.w <= v.w) tx = (map.w - v.w) / 2;
  else tx = clamp(tx, 0, map.w - v.w);
  if (map.h <= v.h) ty = (map.h - v.h) / 2;
  else ty = clamp(ty, 0, map.h - v.h);
  const k = 1 - Math.exp(-9 * dt);
  game.camera.x = lerp(game.camera.x, tx, k);
  game.camera.y = lerp(game.camera.y, ty, k);
}

function snapCamera() {
  const v = game.view, map = game.map, p = game.p;
  let tx = p.x - v.w / 2, ty = p.y - v.h / 2;
  if (map.w <= v.w) tx = (map.w - v.w) / 2; else tx = clamp(tx, 0, map.w - v.w);
  if (map.h <= v.h) ty = (map.h - v.h) / 2; else ty = clamp(ty, 0, map.h - v.h);
  game.camera.x = tx;
  game.camera.y = ty;
}

/* ----------------------------- Actualización ----------------------------- */
function update(dt) {
  const p = game.p;
  game.time += dt;
  p.playTime += dt;
  game.shake = Math.max(0, game.shake - dt * 34);
  game.portalCd = Math.max(0, game.portalCd - dt);
  game.shrineCd = Math.max(0, game.shrineCd - dt);
  p.atkCd = Math.max(0, p.atkCd - dt);
  p.skillCd = Math.max(0, p.skillCd - dt);
  p.healCd = Math.max(0, p.healCd - dt);
  p.invuln = Math.max(0, p.invuln - dt);
  p.atkAnim = Math.max(0, p.atkAnim - dt);
  p.hitFlash = Math.max(0, p.hitFlash - dt);

  if (game.endingTimer > 0) {
    game.endingTimer -= dt;
    if (game.endingTimer <= 0) {
      showEnding();
      return;
    }
  }

  updateCamera(dt);

  /* Movimiento del jugador */
  let mx = 0, my = 0;
  if (keys.w || keys.arrowup) my -= 1;
  if (keys.s || keys.arrowdown) my += 1;
  if (keys.a || keys.arrowleft) mx -= 1;
  if (keys.d || keys.arrowright) mx += 1;
  if (joy.active) { mx = joy.dx; my = joy.dy; }
  const len = Math.hypot(mx, my);
  if (len > 0.08) {
    const nx = mx / (len > 1 ? len : 1);
    const ny = my / (len > 1 ? len : 1);
    p.dir = Math.atan2(ny, nx);
    moveEntity(p, nx * p.speed * dt, ny * p.speed * dt, game.map);
  }

  updateWeather(dt);
  updateEnemies(dt);
  updateBoss(dt);
  updateProjectiles(dt);
  updateEffects(dt);
  updateParticles(dt);
  updatePickups(dt);

  /* Portales */
  if (game.portalCd <= 0 && !game.transition) {
    for (const portal of game.map.portals) {
      if (dist(p.x, p.y, portal.x, portal.y) < portal.r * 0.6 + 6) {
        tryPortal(portal);
        break;
      }
    }
  }

  /* Interacción cercana */
  game.interact = findInteract();
  updatePrompt();

  /* Guardado automático */
  game.saveTimer += dt;
  if (game.saveTimer > 25) { game.saveTimer = 0; saveGame(true); }

  updateHUD();
}

function updateWeather(dt) {
  const map = game.map;
  for (const w of game.weather) {
    w.ph += dt * 1.6;
    w.x += (w.vx + Math.sin(w.ph) * 10) * dt;
    w.y += w.vy * dt;
    if (w.x < -20) w.x = map.w + 10;
    if (w.x > map.w + 20) w.x = -10;
    if (w.y < -20) w.y = map.h + 10;
    if (w.y > map.h + 20) w.y = -10;
  }
}

function updateEnemies(dt) {
  const p = game.p, map = game.map;
  for (const e of game.enemies) {
    if (e.dead) continue;
    e.hitFlash = Math.max(0, e.hitFlash - dt);
    e.atkCd = Math.max(0, e.atkCd - dt);

    if (e.kx || e.ky) {
      moveEntity(e, e.kx * dt, e.ky * dt, map);
      e.kx *= Math.pow(0.02, dt);
      e.ky *= Math.pow(0.02, dt);
    }

    const d = dist(e.x, e.y, p.x, p.y);
    const a = Math.atan2(p.y - e.y, p.x - e.x);

    if (e.state === 'windup') {
      e.timer -= dt;
      e.dir = a;
      if (e.timer <= 0) {
        if (dist(e.x, e.y, p.x, p.y) < e.r + p.r + 26) {
          damagePlayer(e.dmg);
        }
        e.state = 'idle';
        e.atkCd = e.type === 'ghost' ? 1.6 : 1.15;
      }
      continue;
    }

    if (e.type === 'ghost') {
      e.shootCd -= dt;
      if (d < e.aggro) {
        e.dir = a;
        if (d > 150) moveEntity(e, Math.cos(a) * e.speed * dt, Math.sin(a) * e.speed * dt, map);
        else if (d < 100) moveEntity(e, -Math.cos(a) * e.speed * 0.5 * dt, -Math.sin(a) * e.speed * 0.5 * dt, map);
        if (e.shootCd <= 0 && d < 380) {
          e.shootCd = 3.1;
          e.state = 'windup';
          e.timer = 0.45;
          e.windupKind = 'bolt';
        }
      } else {
        e.wander -= dt;
        if (e.wander <= 0) {
          e.wander = rand(1.5, 3.5);
          e.wx = e.home.x + rand(-70, 70);
          e.wy = e.home.y + rand(-50, 50);
        }
        const wa = Math.atan2(e.wy - e.y, e.wx - e.x);
        if (dist(e.x, e.y, e.wx, e.wy) > 8) moveEntity(e, Math.cos(wa) * 26 * dt, Math.sin(wa) * 26 * dt, map);
      }
    } else {
      /* limo */
      if (d < e.aggro) {
        e.dir = a;
        if (d > e.r + p.r + 6) {
          moveEntity(e, Math.cos(a) * e.speed * dt, Math.sin(a) * e.speed * dt, map);
        }
        if (d < e.r + p.r + 18 && e.atkCd <= 0) {
          e.state = 'windup';
          e.timer = 0.4;
        }
      } else {
        e.wander -= dt;
        if (e.wander <= 0) {
          e.wander = rand(1.2, 3);
          e.wx = e.home.x + rand(-80, 80);
          e.wy = e.home.y + rand(-60, 60);
        }
        const wa = Math.atan2(e.wy - e.y, e.wx - e.x);
        if (dist(e.x, e.y, e.wx, e.wy) > 10) moveEntity(e, Math.cos(wa) * 24 * dt, Math.sin(wa) * 24 * dt, map);
      }
    }
  }

  /* Separación suave entre enemigos */
  for (let i = 0; i < game.enemies.length; i++) {
    const a = game.enemies[i];
    if (a.dead) continue;
    for (let j = i + 1; j < game.enemies.length; j++) {
      const b = game.enemies[j];
      if (b.dead) continue;
      const dx = b.x - a.x, dy = b.y - a.y;
      const dd = Math.hypot(dx, dy);
      const min = a.r + b.r;
      if (dd > 0.01 && dd < min) {
        const push = (min - dd) / 2;
        a.x -= (dx / dd) * push;
        a.y -= (dy / dd) * push;
        b.x += (dx / dd) * push;
        b.y += (dy / dd) * push;
      }
    }
  }
  game.enemies = game.enemies.filter((e) => !e.dead);
}

function updateBoss(dt) {
  const b = game.boss;
  if (!b || b.dead) return;
  const p = game.p, map = game.map;
  b.hitFlash = Math.max(0, b.hitFlash - dt);

  if (!b.active) {
    if (dist(b.x, b.y, p.x, p.y) < 400) {
      b.active = true;
      AudioFX.boss();
      game.shake = 12;
      toast('El Señor de la Ceniza despierta', 'danger');
      showBossBar();
      updateBossBar();
    }
    return;
  }

  if (b.hp < b.maxHp * 0.5 && b.phase === 1) {
    b.phase = 2;
    b.speed = 76;
    toast('El Señor de la Ceniza arde con más furia', 'danger');
    game.shake = 14;
    addRing(b.x, b.y, 130, '#ff8a4c', 0.9);
    burst(b.x, b.y, '#ff8a4c', 30, 200, 5);
    AudioFX.boss();
  }

  if (b.kx || b.ky) {
    moveEntity(b, b.kx * dt, b.ky * dt, map);
    b.kx *= Math.pow(0.02, dt);
    b.ky *= Math.pow(0.02, dt);
  }

  const d = dist(b.x, b.y, p.x, p.y);
  const a = Math.atan2(p.y - b.y, p.x - b.x);
  b.dir = a;

  if (b.state === 'chase') {
    b.atkCd = Math.max(0, b.atkCd - dt);
    if (d > 120) moveEntity(b, Math.cos(a) * b.speed * dt, Math.sin(a) * b.speed * dt, map);
    if (b.atkCd <= 0) {
      if (d < 230) {
        b.state = 'slam';
        b.timer = 0.95;
        b.slamX = p.x;
        b.slamY = p.y;
        b.slamR = 128;
        game.effects.push({ kind: 'telegraph', x: b.slamX, y: b.slamY, r: b.slamR, life: 0.95, max: 0.95, color: '#ff6a4a' });
      } else if (d < 520) {
        b.state = 'volley';
        b.timer = 0.6;
      } else {
        b.atkCd = 0.4;
      }
    }
  } else if (b.state === 'slam') {
    b.timer -= dt;
    if (b.timer <= 0) {
      if (dist(b.slamX, b.slamY, p.x, p.y) < b.slamR + p.r) damagePlayer(b.dmg);
      burst(b.slamX, b.slamY, '#ff8a4c', 34, 260, 5);
      addRing(b.slamX, b.slamY, b.slamR, '#ff8a4c', 0.45);
      game.shake = 16;
      AudioFX.hit();
      b.state = 'chase';
      b.atkCd = b.phase === 2 ? 1.15 : 1.7;
      b.volleyCd = 2.4;
    }
  } else if (b.state === 'volley') {
    b.timer -= dt;
    if (b.timer <= 0) {
      const count = b.phase === 2 ? 7 : 5;
      const spread = 0.62;
      for (let i = 0; i < count; i++) {
        const t = count === 1 ? 0 : i / (count - 1) - 0.5;
        const ang = a + t * spread;
        game.projectiles.push({
          x: b.x + Math.cos(ang) * 30, y: b.y + Math.sin(ang) * 30,
          vx: Math.cos(ang) * 205, vy: Math.sin(ang) * 205,
          r: 7, dmg: b.phase === 2 ? 15 : 12, life: 3.2, color: '#ff9a5a'
        });
      }
      AudioFX.tone(220, 0.25, 'sawtooth', 0.045, -110);
      b.state = 'chase';
      b.atkCd = b.phase === 2 ? 1.8 : 2.6;
    }
  }
}

function updateProjectiles(dt) {
  const p = game.p, map = game.map;
  for (const pr of game.projectiles) {
    pr.x += pr.vx * dt;
    pr.y += pr.vy * dt;
    pr.life -= dt;
    if (pr.life <= 0) continue;
    if (pr.x < 0 || pr.y < 0 || pr.x > map.w || pr.y > map.h) { pr.life = 0; continue; }
    if (dist(pr.x, pr.y, p.x, p.y) < pr.r + p.r) {
      damagePlayer(pr.dmg);
      pr.life = 0;
      burst(pr.x, pr.y, pr.color, 12, 120, 3);
    }
  }
  game.projectiles = game.projectiles.filter((pr) => pr.life > 0);
}

function updateEffects(dt) {
  for (const fx of game.effects) fx.life -= dt;
  game.effects = game.effects.filter((fx) => fx.life > 0);
}

function updateParticles(dt) {
  for (const pt of game.particles) {
    pt.life -= dt;
    pt.x += pt.vx * dt;
    pt.y += pt.vy * dt;
    pt.vy += (pt.grav || 0) * dt;
    pt.vx *= Math.pow(0.2, dt);
  }
  game.particles = game.particles.filter((pt) => pt.life > 0);

  for (const n of game.numbers) {
    n.life -= dt;
    n.y += n.vy * dt;
    n.vy *= Math.pow(0.25, dt);
  }
  game.numbers = game.numbers.filter((n) => n.life > 0);
}

function updatePickups(dt) {
  /* Reservado para futuras recogidas; los objetos se entregan al instante. */
}

/* ===========================================================
   LA ESPADA CELESTIAL — renderizado
   Canvas 2D: mundo, personajes, efectos y marcador de objetivo.
   =========================================================== */
'use strict';

const canvas = $('game');
const ctx = canvas.getContext('2d');

const PATH_COLORS = {
  village: '#4b4434',
  forest: '#383325',
  ruins: '#3a3440',
  temple: '#2b2130'
};

let vignette = null;

function resize() {
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const cssW = Math.max(320, window.innerWidth);
  const cssH = Math.max(320, window.innerHeight);
  canvas.width = Math.round(cssW * dpr);
  canvas.height = Math.round(cssH * dpr);

  const targetW = Math.min(800, Math.max(330, cssW * 0.86));
  const zoom = cssW / targetW;

  game.view.dpr = dpr;
  game.view.zoom = zoom;
  game.view.w = cssW / zoom;
  game.view.h = cssH / zoom;
  game.view.cssW = cssW;
  game.view.cssH = cssH;

  vignette = ctx.createRadialGradient(cssW / 2, cssH * 0.48, Math.min(cssW, cssH) * 0.3, cssW / 2, cssH * 0.5, Math.max(cssW, cssH) * 0.78);
  vignette.addColorStop(0, 'rgba(0,0,0,0)');
  vignette.addColorStop(1, 'rgba(0,0,0,0.62)');

  if (game.map) snapCamera();
}

/* ----------------------------- Utilidades de dibujo ----------------------------- */
function inView(x, y, m = 130) {
  const c = game.camera, v = game.view;
  return x > c.x - m && x < c.x + v.w + m && y > c.y - m && y < c.y + v.h + m;
}

function shadow(x, y, rx, ry, alpha = 0.3) {
  ctx.fillStyle = `rgba(0,0,0,${alpha})`;
  ctx.beginPath();
  ctx.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2);
  ctx.fill();
}

function roundRect(x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function label(text, x, y, color = '#f2e8d0', size = 10, weight = 600, alpha = 1) {
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.font = `${weight} ${size}px Inter, system-ui, sans-serif`;
  ctx.textAlign = 'center';
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'rgba(0,0,0,0.72)';
  ctx.strokeText(text, x, y);
  ctx.fillStyle = color;
  ctx.fillText(text, x, y);
  ctx.restore();
}

function hpBar(x, y, w, ratio, color) {
  ctx.fillStyle = 'rgba(0,0,0,0.55)';
  roundRect(x - w / 2, y, w, 4, 2);
  ctx.fill();
  ctx.fillStyle = color;
  roundRect(x - w / 2, y, Math.max(0, w * ratio), 4, 2);
  ctx.fill();
}

/* ----------------------------- Terreno ----------------------------- */
function ensureDecor(map) {
  if (map._decor) return;
  const rng = mulberry32(map._seed * 131 + 7);
  map._decor = [];
  for (let i = 0; i < 150; i++) {
    map._decor.push({
      x: rng() * map.w,
      y: rng() * map.h,
      r: 12 + rng() * 46,
      c: rng() < 0.55 ? map.accent : (rng() < 0.5 ? '#000000' : '#ffffff'),
      a: 0.03 + rng() * 0.07
    });
  }
}

function drawGround(map) {
  ctx.fillStyle = map.ground;
  ctx.fillRect(0, 0, map.w, map.h);
  ensureDecor(map);
  for (const d of map._decor) {
    if (!inView(d.x, d.y, 60)) continue;
    ctx.globalAlpha = d.a;
    ctx.fillStyle = d.c;
    ctx.beginPath();
    ctx.ellipse(d.x, d.y, d.r, d.r * 0.6, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  const pc = PATH_COLORS[map.id] || '#3e3a2c';
  for (const p of map.paths) {
    ctx.strokeStyle = pc;
    ctx.lineCap = 'round';
    ctx.lineWidth = p.w;
    ctx.beginPath();
    ctx.moveTo(p.x1, p.y1);
    ctx.lineTo(p.x2, p.y2);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,0.035)';
    ctx.lineWidth = p.w * 0.62;
    ctx.stroke();
  }

  ctx.strokeStyle = 'rgba(0,0,0,0.35)';
  ctx.lineWidth = 14;
  ctx.strokeRect(5, 5, map.w - 10, map.h - 10);
}

/* ----------------------------- Props ----------------------------- */
function drawTree(p) {
  const s = p.s;
  shadow(p.x, p.y + 2, 20 * s, 7 * s, 0.32);
  ctx.fillStyle = '#463323';
  ctx.beginPath();
  ctx.moveTo(p.x - 4 * s, p.y);
  ctx.lineTo(p.x - 2.5 * s, p.y - 30 * s);
  ctx.lineTo(p.x + 2.5 * s, p.y - 30 * s);
  ctx.lineTo(p.x + 4 * s, p.y);
  ctx.closePath();
  ctx.fill();

  const dark = p.tone ? '#183428' : '#16301e';
  const mid = p.tone ? '#234a35' : '#21452b';
  const lite = p.tone ? '#2f5d44' : '#2c5c38';
  ctx.fillStyle = dark;
  ctx.beginPath();
  ctx.arc(p.x - 13 * s, p.y - 38 * s, 17 * s, 0, Math.PI * 2);
  ctx.arc(p.x + 13 * s, p.y - 38 * s, 17 * s, 0, Math.PI * 2);
  ctx.arc(p.x, p.y - 50 * s, 20 * s, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = mid;
  ctx.beginPath();
  ctx.arc(p.x - 7 * s, p.y - 44 * s, 14 * s, 0, Math.PI * 2);
  ctx.arc(p.x + 9 * s, p.y - 42 * s, 12 * s, 0, Math.PI * 2);
  ctx.arc(p.x + 1 * s, p.y - 55 * s, 14 * s, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = lite;
  ctx.globalAlpha = 0.65;
  ctx.beginPath();
  ctx.arc(p.x - 5 * s, p.y - 52 * s, 8 * s, 0, Math.PI * 2);
  ctx.arc(p.x + 6 * s, p.y - 47 * s, 5 * s, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 1;
}

function drawRock(p) {
  const s = p.s;
  shadow(p.x, p.y + 2, 16 * s, 5 * s, 0.3);
  ctx.fillStyle = '#4a4d55';
  ctx.beginPath();
  for (let i = 0; i < 7; i++) {
    const a = (i / 7) * Math.PI * 2;
    const rr = (11 + Math.sin(i * 2.7 + p.x) * 3) * s;
    const px = p.x + Math.cos(a) * rr;
    const py = p.y - 6 * s + Math.sin(a) * rr * 0.7;
    i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
  }
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.12)';
  ctx.beginPath();
  ctx.ellipse(p.x - 3 * s, p.y - 12 * s, 7 * s, 4 * s, -0.4, 0, Math.PI * 2);
  ctx.fill();
}

function drawBush(p) {
  const s = p.s;
  shadow(p.x, p.y + 2, 13 * s, 4 * s, 0.24);
  ctx.fillStyle = '#2a4f32';
  ctx.beginPath();
  ctx.arc(p.x - 7 * s, p.y - 6 * s, 8 * s, 0, Math.PI * 2);
  ctx.arc(p.x + 7 * s, p.y - 6 * s, 8 * s, 0, Math.PI * 2);
  ctx.arc(p.x, p.y - 11 * s, 9 * s, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#396943';
  ctx.beginPath();
  ctx.arc(p.x - 2 * s, p.y - 10 * s, 5 * s, 0, Math.PI * 2);
  ctx.fill();
}

function drawHouse(p) {
  const { x, y, w, h } = p;
  shadow(x, y + 4, w * 0.54, 12, 0.34);
  const wall = p.tone ? '#3d3142' : '#3b322a';
  const wall2 = p.tone ? '#2c2433' : '#2b241e';
  const g = ctx.createLinearGradient(0, y - h, 0, y);
  g.addColorStop(0, wall);
  g.addColorStop(1, wall2);
  ctx.fillStyle = g;
  ctx.fillRect(x - w / 2, y - h, w, h);

  ctx.fillStyle = p.tone ? '#5f3d52' : '#743d34';
  ctx.beginPath();
  ctx.moveTo(x - w / 2 - 14, y - h + 6);
  ctx.lineTo(x, y - h - 44);
  ctx.lineTo(x + w / 2 + 14, y - h + 6);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.09)';
  ctx.beginPath();
  ctx.moveTo(x - w / 2 - 14, y - h + 6);
  ctx.lineTo(x, y - h - 44);
  ctx.lineTo(x - w * 0.05, y - h + 6);
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = 'rgba(0,0,0,0.22)';
  ctx.fillRect(x - w / 2, y - h + 6, w, 6);

  const dw = 30, dh = 46;
  ctx.fillStyle = '#2a1d14';
  ctx.fillRect(x - dw / 2, y - dh, dw, dh);
  ctx.fillStyle = '#6b4a2a';
  ctx.fillRect(x - dw / 2 + 3, y - dh + 4, dw - 6, dh - 4);
  ctx.fillStyle = '#d9a44a';
  ctx.beginPath();
  ctx.arc(x + 9, y - dh / 2 - 3, 2, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = 'rgba(255,214,138,0.85)';
  ctx.fillRect(x - w / 2 + 26, y - h + 34, 22, 18);
  ctx.fillRect(x + w / 2 - 48, y - h + 34, 22, 18);
  ctx.strokeStyle = 'rgba(0,0,0,0.4)';
  ctx.lineWidth = 2;
  ctx.strokeRect(x - w / 2 + 26, y - h + 34, 22, 18);
  ctx.strokeRect(x + w / 2 - 48, y - h + 34, 22, 18);

  ctx.fillStyle = '#4a3226';
  ctx.fillRect(x + w * 0.24, y - h - 26, 14, 30);
}

function drawFountain(p) {
  const t = game.time;
  shadow(p.x, p.y + 4, 62, 18, 0.35);
  ctx.fillStyle = '#4a4e55';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y, 60, 26, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#5b6068';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y - 4, 60, 26, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#203d4f';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y - 4, 50, 20, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(120,200,235,0.55)';
  for (let i = 0; i < 3; i++) {
    const rr = 14 + i * 12;
    ctx.beginPath();
    ctx.ellipse(p.x + Math.sin(t * 1.2 + i) * 4, p.y - 4 + Math.cos(t + i) * 2, rr, rr * 0.4, 0, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(150,225,255,${0.25 - i * 0.05})`;
    ctx.lineWidth = 2;
    ctx.stroke();
  }
  ctx.fillStyle = '#4f545c';
  ctx.fillRect(p.x - 5, p.y - 46, 10, 40);
  ctx.beginPath();
  ctx.arc(p.x, p.y - 50, 8, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(170,230,255,0.75)';
  ctx.beginPath();
  ctx.arc(p.x, p.y - 52, 3, 0, Math.PI * 2);
  ctx.fill();
}

function drawPillar(p) {
  const s = p.s;
  shadow(p.x, p.y + 2, 18 * s, 6 * s, 0.3);
  ctx.fillStyle = '#514b57';
  ctx.fillRect(p.x - 20 * s, p.y - 8 * s, 40 * s, 10 * s);
  const g = ctx.createLinearGradient(p.x - 14 * s, 0, p.x + 14 * s, 0);
  g.addColorStop(0, '#3b3642');
  g.addColorStop(0.4, '#5c5566');
  g.addColorStop(1, '#332e3a');
  ctx.fillStyle = g;
  const h = (p.broken ? 44 : 78) * s;
  ctx.fillRect(p.x - 12 * s, p.y - h, 24 * s, h);
  ctx.fillStyle = '#5d5668';
  ctx.fillRect(p.x - 17 * s, p.y - h - 8 * s, 34 * s, 9 * s);
  if (p.broken) {
    ctx.fillStyle = '#3b3642';
    ctx.beginPath();
    ctx.moveTo(p.x - 12 * s, p.y - h);
    ctx.lineTo(p.x + 3 * s, p.y - h - 10 * s);
    ctx.lineTo(p.x + 12 * s, p.y - h + 4 * s);
    ctx.closePath();
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(255,255,255,0.08)';
  ctx.fillRect(p.x - 8 * s, p.y - h, 4 * s, h);
}

function drawCrystal(p) {
  const t = game.time;
  const pulse = 0.75 + Math.sin(t * 2 + p.x) * 0.25;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(p.x, p.y - 16, 2, p.x, p.y - 16, 32);
  g.addColorStop(0, p.color || '#9fd8ff');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.globalAlpha = 0.35 * pulse;
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(p.x, p.y - 16, 32, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  shadow(p.x, p.y + 1, 12, 4, 0.3);
  ctx.fillStyle = p.color || '#9fd8ff';
  ctx.globalAlpha = 0.85;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y - 36);
  ctx.lineTo(p.x + 9, p.y - 18);
  ctx.lineTo(p.x + 4, p.y);
  ctx.lineTo(p.x - 5, p.y);
  ctx.lineTo(p.x - 9, p.y - 18);
  ctx.closePath();
  ctx.fill();
  ctx.globalAlpha = 1;
  ctx.fillStyle = 'rgba(255,255,255,0.6)';
  ctx.beginPath();
  ctx.moveTo(p.x, p.y - 33);
  ctx.lineTo(p.x + 3, p.y - 18);
  ctx.lineTo(p.x - 1, p.y - 4);
  ctx.closePath();
  ctx.fill();
}

function drawTorch(p) {
  const t = game.time;
  shadow(p.x, p.y + 1, 7, 3, 0.28);
  ctx.fillStyle = '#4a3524';
  ctx.fillRect(p.x - 2, p.y - 30, 4, 30);
  ctx.fillStyle = '#6b5037';
  ctx.fillRect(p.x - 5, p.y - 34, 10, 5);
  const fl = Math.sin(t * 9 + p.x) * 2;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(p.x, p.y - 42, 1, p.x, p.y - 42, 26);
  g.addColorStop(0, 'rgba(255,190,90,0.55)');
  g.addColorStop(1, 'rgba(255,120,40,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(p.x, p.y - 42, 26, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = '#ffb43c';
  ctx.beginPath();
  ctx.ellipse(p.x + fl * 0.4, p.y - 40, 5, 9 + fl * 0.4, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#ffe9a8';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y - 39, 2.5, 5, 0, 0, Math.PI * 2);
  ctx.fill();
}

function drawBones(p) {
  ctx.strokeStyle = 'rgba(214,209,196,0.55)';
  ctx.lineWidth = 2.5;
  ctx.beginPath();
  ctx.moveTo(p.x - 8, p.y - 2);
  ctx.lineTo(p.x + 8, p.y);
  ctx.moveTo(p.x - 2, p.y - 6);
  ctx.lineTo(p.x + 3, p.y + 2);
  ctx.stroke();
  ctx.fillStyle = 'rgba(214,209,196,0.6)';
  ctx.beginPath();
  ctx.arc(p.x - 10, p.y - 3, 3, 0, Math.PI * 2);
  ctx.arc(p.x + 10, p.y + 1, 3, 0, Math.PI * 2);
  ctx.fill();
}

function drawFlower(p) {
  ctx.strokeStyle = '#3d6b44';
  ctx.lineWidth = 1.4;
  ctx.beginPath();
  ctx.moveTo(p.x, p.y);
  ctx.lineTo(p.x, p.y - 7);
  ctx.stroke();
  ctx.fillStyle = p.color || '#e3c26a';
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2;
    ctx.beginPath();
    ctx.arc(p.x + Math.cos(a) * 2.6, p.y - 8 + Math.sin(a) * 2.6, 2, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = '#fff2c0';
  ctx.beginPath();
  ctx.arc(p.x, p.y - 8, 1.3, 0, Math.PI * 2);
  ctx.fill();
}

function drawShrine(p) {
  const t = game.time;
  shadow(p.x, p.y + 2, 24, 7, 0.35);
  ctx.fillStyle = '#4a4652';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y, 24, 9, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#5b5664';
  ctx.fillRect(p.x - 14, p.y - 18, 28, 18);
  ctx.fillStyle = '#3e3946';
  ctx.fillRect(p.x - 18, p.y - 22, 36, 6);

  const fl = Math.sin(t * 3.4) * 2;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(p.x, p.y - 40, 2, p.x, p.y - 40, 44);
  g.addColorStop(0, 'rgba(160,235,255,0.45)');
  g.addColorStop(1, 'rgba(80,180,255,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(p.x, p.y - 40, 44, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = '#9fdcff';
  ctx.beginPath();
  ctx.ellipse(p.x + fl * 0.3, p.y - 34, 7, 14, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#e8fbff';
  ctx.beginPath();
  ctx.ellipse(p.x, p.y - 32, 3, 8, 0, 0, Math.PI * 2);
  ctx.fill();
}

/* ----------------------------- Entidades ----------------------------- */
function drawPlayer() {
  const p = game.p;
  const t = game.time;
  const bob = Math.sin(t * 7) * 1.1;
  const blink = p.invuln > 0 && Math.sin(t * 38) > 0;

  shadow(p.x, p.y + 11, 13, 5, 0.35);

  ctx.save();
  ctx.translate(p.x, p.y + bob);
  if (blink) ctx.globalAlpha = 0.5;

  if (p.blade >= 3) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(0, -10, 4, 0, -10, 38);
    g.addColorStop(0, 'rgba(255,228,150,0.22)');
    g.addColorStop(1, 'rgba(255,210,120,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(0, -10, 38, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  /* Capa */
  ctx.fillStyle = '#20364c';
  ctx.beginPath();
  ctx.moveTo(-8, -14);
  ctx.quadraticCurveTo(-14 - Math.sin(t * 4) * 1.5, 2, -6, 8);
  ctx.lineTo(6, 8);
  ctx.quadraticCurveTo(13 + Math.sin(t * 4) * 1.5, 2, 8, -14);
  ctx.closePath();
  ctx.fill();

  /* Cuerpo */
  const bg = ctx.createLinearGradient(0, -22, 0, 6);
  bg.addColorStop(0, '#4f89ad');
  bg.addColorStop(1, '#22415b');
  ctx.fillStyle = bg;
  ctx.beginPath();
  ctx.ellipse(0, -7, 9, 13, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#d8b06a';
  ctx.fillRect(-9, -4, 18, 3);

  /* Cabeza */
  ctx.fillStyle = '#f0c9a0';
  ctx.beginPath();
  ctx.arc(0, -24, 6.6, 0, Math.PI * 2);
  ctx.fill();

  /* Pelo */
  ctx.fillStyle = '#2b2028';
  ctx.beginPath();
  ctx.arc(0, -26, 6.8, Math.PI * 1.05, Math.PI * 1.95);
  ctx.fill();
  ctx.beginPath();
  ctx.ellipse(-5.6, -22, 2.2, 4, 0.3, 0, Math.PI * 2);
  ctx.fill();

  /* Ojos orientados */
  const ex = Math.cos(p.dir) * 2.2;
  const ey = Math.sin(p.dir) * 1.3;
  ctx.fillStyle = '#1b2230';
  ctx.beginPath();
  ctx.arc(-2.2 + ex, -23 + ey, 1.25, 0, Math.PI * 2);
  ctx.arc(2.2 + ex, -23 + ey, 1.25, 0, Math.PI * 2);
  ctx.fill();

  /* Bufanda */
  ctx.fillStyle = '#b8452f';
  ctx.beginPath();
  ctx.ellipse(0, -16, 6.5, 2.6, 0, 0, Math.PI * 2);
  ctx.fill();

  /* Espada */
  let ang = p.dir + 0.95;
  if (p.atkAnim > 0) {
    const pr = 1 - p.atkAnim / 0.2;
    ang = p.dir - 1.15 + pr * 2.3;
  }
  ctx.save();
  ctx.translate(Math.cos(p.dir) * 4, -8 + Math.sin(p.dir) * 3);
  ctx.rotate(ang);
  const bcol = bladeColor();
  ctx.strokeStyle = 'rgba(255,255,255,0.18)';
  ctx.lineWidth = 8;
  ctx.beginPath();
  ctx.moveTo(4, 0);
  ctx.lineTo(30, 0);
  ctx.stroke();
  const sg = ctx.createLinearGradient(4, 0, 30, 0);
  sg.addColorStop(0, '#8a7a5a');
  sg.addColorStop(0.25, bcol);
  sg.addColorStop(1, '#ffffff');
  ctx.strokeStyle = sg;
  ctx.lineWidth = 3.4;
  ctx.beginPath();
  ctx.moveTo(4, 0);
  ctx.lineTo(30, 0);
  ctx.stroke();
  ctx.fillStyle = '#c9a24d';
  ctx.fillRect(1, -4.5, 3, 9);
  ctx.restore();

  ctx.restore();

  if (p.hitFlash > 0) {
    ctx.fillStyle = `rgba(255,70,70,${p.hitFlash * 1.2})`;
    ctx.beginPath();
    ctx.arc(p.x, p.y - 10, 20, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawSlime(e) {
  const t = game.time;
  const bob = Math.sin(t * 5 + e.x * 0.1) * 2;
  const sq = 1 + Math.sin(t * 6 + e.x) * 0.07;
  shadow(e.x, e.y + 8, 15, 5, 0.3);
  ctx.save();
  ctx.translate(e.x, e.y + 4 + bob * 0.3);
  const g = ctx.createLinearGradient(0, -22, 0, 4);
  g.addColorStop(0, '#9fe08a');
  g.addColorStop(0.55, '#5fae5f');
  g.addColorStop(1, '#356b3f');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(0, -6, 16 / sq, 12 * sq, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.35)';
  ctx.beginPath();
  ctx.ellipse(-5, -12, 5, 3.4, -0.4, 0, Math.PI * 2);
  ctx.fill();

  const ex = Math.cos(e.dir) * 2;
  const ey = Math.sin(e.dir) * 1.4;
  ctx.fillStyle = '#f6fff0';
  ctx.beginPath();
  ctx.arc(-5 + ex, -8 + ey, 3.2, 0, Math.PI * 2);
  ctx.arc(5 + ex, -8 + ey, 3.2, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#1b2a1c';
  ctx.beginPath();
  ctx.arc(-5 + ex * 1.4, -8 + ey * 1.4, 1.5, 0, Math.PI * 2);
  ctx.arc(5 + ex * 1.4, -8 + ey * 1.4, 1.5, 0, Math.PI * 2);
  ctx.fill();
  if (e.hitFlash > 0) {
    ctx.fillStyle = `rgba(255,255,255,${e.hitFlash * 3})`;
    ctx.beginPath();
    ctx.ellipse(0, -6, 16, 12, 0, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  if (e.hp < e.maxHp) hpBar(e.x, e.y - 32, 30, e.hp / e.maxHp, '#7fd66f');
  if (e.state === 'windup') {
    ctx.strokeStyle = 'rgba(255,90,80,0.85)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(e.x, e.y - 4, e.r + 6, -0.6, 0.6);
    ctx.stroke();
  }
}

function drawGhost(e) {
  const t = game.time;
  const fl = Math.sin(t * 3 + e.x * 0.05) * 4;
  shadow(e.x, e.y + 10, 12, 4, 0.18);
  ctx.save();
  ctx.translate(e.x, e.y - 10 + fl);
  ctx.globalAlpha = 0.92;
  const g = ctx.createLinearGradient(0, -22, 0, 18);
  g.addColorStop(0, 'rgba(190,225,255,0.95)');
  g.addColorStop(1, 'rgba(70,110,160,0.55)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(0, -10, 12, Math.PI, 0);
  ctx.lineTo(12, 8);
  for (let i = 0; i < 4; i++) {
    ctx.quadraticCurveTo(9 - i * 6, 16 + Math.sin(t * 5 + i) * 3, 6 - i * 6, 8);
  }
  ctx.closePath();
  ctx.fill();

  ctx.fillStyle = 'rgba(255,255,255,0.14)';
  ctx.beginPath();
  ctx.arc(-4, -14, 5, 0, Math.PI * 2);
  ctx.fill();

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const eyeGlow = ctx.createRadialGradient(0, -10, 1, 0, -10, 16);
  eyeGlow.addColorStop(0, 'rgba(160,240,255,0.6)');
  eyeGlow.addColorStop(1, 'rgba(160,240,255,0)');
  ctx.fillStyle = eyeGlow;
  ctx.beginPath();
  ctx.arc(0, -10, 16, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  ctx.fillStyle = '#d9fbff';
  ctx.beginPath();
  ctx.ellipse(-4.4, -11, 2.3, 3.1, 0, 0, Math.PI * 2);
  ctx.ellipse(4.4, -11, 2.3, 3.1, 0, 0, Math.PI * 2);
  ctx.fill();

  if (e.hitFlash > 0) {
    ctx.globalAlpha = e.hitFlash * 3;
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.arc(0, -8, 15, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  if (e.hp < e.maxHp) hpBar(e.x, e.y - 40, 30, e.hp / e.maxHp, '#a8d8ff');
  if (e.state === 'windup') {
    ctx.strokeStyle = 'rgba(160,230,255,0.9)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(e.x, e.y - 8, e.r + 8, -0.7, 0.7);
    ctx.stroke();
  }
}

function drawBoss(b) {
  const t = game.time;
  const fl = Math.sin(t * 2.2) * 1.5;
  shadow(b.x, b.y + 16, 38, 13, 0.42);
  ctx.save();
  ctx.translate(b.x, b.y + fl);
  ctx.fillStyle = '#3b1f22';
  ctx.beginPath();
  ctx.moveTo(-26, -30);
  ctx.quadraticCurveTo(-40, 4, -24, 18);
  ctx.lineTo(24, 18);
  ctx.quadraticCurveTo(40, 4, 26, -30);
  ctx.closePath();
  ctx.fill();

  const g = ctx.createLinearGradient(0, -52, 0, 14);
  g.addColorStop(0, '#5a3b33');
  g.addColorStop(0.5, '#37262a');
  g.addColorStop(1, '#1d151b');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.ellipse(0, -20, 26, 32, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#4a3038';
  ctx.beginPath();
  ctx.ellipse(-26, -36, 12, 9, -0.3, 0, Math.PI * 2);
  ctx.ellipse(26, -36, 12, 9, 0.3, 0, Math.PI * 2);
  ctx.fill();

  /* Núcleo de ceniza */
  const pulse = 0.8 + Math.sin(t * 4) * 0.2;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const cg = ctx.createRadialGradient(0, -26, 2, 0, -26, 22);
  cg.addColorStop(0, `rgba(255,170,90,${0.9 * pulse})`);
  cg.addColorStop(1, 'rgba(255,90,40,0)');
  ctx.fillStyle = cg;
  ctx.beginPath();
  ctx.arc(0, -26, 22, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
  ctx.fillStyle = '#ffb066';
  ctx.beginPath();
  ctx.arc(0, -26, 6, 0, Math.PI * 2);
  ctx.fill();

  /* Cabeza y corona */
  ctx.fillStyle = '#2a2026';
  ctx.beginPath();
  ctx.arc(0, -54, 12, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#ffb15e';
  ctx.beginPath();
  ctx.arc(-4, -55, 2, 0, Math.PI * 2);
  ctx.arc(4, -55, 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#c99a4a';
  ctx.beginPath();
  ctx.moveTo(-12, -62);
  ctx.lineTo(-7, -74);
  ctx.lineTo(-2, -63);
  ctx.lineTo(3, -76);
  ctx.lineTo(7, -62);
  ctx.lineTo(12, -70);
  ctx.lineTo(12, -58);
  ctx.lineTo(-12, -58);
  ctx.closePath();
  ctx.fill();

  /* Espada del rey */
  ctx.save();
  ctx.translate(28, -18);
  ctx.rotate(0.35 + Math.sin(t * 2) * 0.05);
  ctx.fillStyle = '#6b4a3a';
  ctx.fillRect(-3, -4, 6, 12);
  ctx.fillStyle = '#8a6a52';
  ctx.fillRect(-10, -7, 20, 5);
  const bg2 = ctx.createLinearGradient(0, -8, 0, -70);
  bg2.addColorStop(0, '#8f7f78');
  bg2.addColorStop(1, '#e0cfbf');
  ctx.fillStyle = bg2;
  ctx.beginPath();
  ctx.moveTo(-4, -8);
  ctx.lineTo(0, -72);
  ctx.lineTo(4, -8);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  if (b.hitFlash > 0) {
    ctx.globalAlpha = b.hitFlash * 2.2;
    ctx.fillStyle = '#fff';
    ctx.beginPath();
    ctx.ellipse(0, -24, 30, 40, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.globalAlpha = 1;
  }
  ctx.restore();

  if (b.phase === 2) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < 5; i++) {
      const a = t * 1.6 + i * 1.25;
      const rx = b.x + Math.cos(a) * (26 + Math.sin(t * 3 + i) * 5);
      const ry = b.y - 26 + Math.sin(a) * 14;
      ctx.fillStyle = 'rgba(255,140,70,0.5)';
      ctx.beginPath();
      ctx.arc(rx, ry, 3 + Math.sin(t * 4 + i) * 1.2, 0, Math.PI * 2);
      ctx.fill();
    }
    ctx.restore();
  }
}

function drawNpc(npc) {
  const t = game.time;
  const bob = Math.sin(t * 3 + npc.x) * 1.2;
  shadow(npc.x, npc.y + 2, 12, 4.4, 0.32);
  ctx.save();
  ctx.translate(npc.x, npc.y + bob);

  /* Túnica */
  ctx.fillStyle = npc.robe;
  ctx.beginPath();
  ctx.moveTo(-9, -22);
  ctx.quadraticCurveTo(-13, -4, -8, 4);
  ctx.lineTo(8, 4);
  ctx.quadraticCurveTo(13, -4, 9, -22);
  ctx.closePath();
  ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.1)';
  ctx.beginPath();
  ctx.moveTo(-9, -22);
  ctx.lineTo(-2, -2);
  ctx.lineTo(-8, 4);
  ctx.closePath();
  ctx.fill();

  /* Cabeza */
  ctx.fillStyle = '#e8c09a';
  ctx.beginPath();
  ctx.arc(0, -30, 6.4, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = npc.hair;
  ctx.beginPath();
  ctx.arc(0, -32, 6.6, Math.PI * 1.02, Math.PI * 1.98);
  ctx.fill();
  if (npc.id === 'mira') {
    ctx.beginPath();
    ctx.arc(0, -35, 3.2, 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.fillStyle = '#1c2230';
  ctx.beginPath();
  ctx.arc(-2.2, -29, 1, 0, Math.PI * 2);
  ctx.arc(2.2, -29, 1, 0, Math.PI * 2);
  ctx.fill();

  /* Bastón / martillo */
  if (npc.id === 'mira') {
    ctx.strokeStyle = '#6b5236';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(11, 4);
    ctx.lineTo(13, -34);
    ctx.stroke();
    ctx.fillStyle = '#9fdcff';
    ctx.beginPath();
    ctx.arc(13, -37, 3.4, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.strokeStyle = '#5a4330';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(11, 3);
    ctx.lineTo(15, -26);
    ctx.stroke();
    ctx.fillStyle = '#7d8087';
    ctx.fillRect(8, -30, 14, 6);
  }
  ctx.restore();

  const p = game.p;
  const d = dist(p.x, p.y, npc.x, npc.y);
  if (d < 150) label(npc.name, npc.x, npc.y - 50, '#f0e6cd', 10, 600, 0.95);

  let marker = null;
  if (npc.id === 'mira' && p.stage === 1) marker = '!';
  if (npc.id === 'herrero' && p.blade < 3 && p.gold >= 60) marker = '⚒';
  if (marker) {
    const my = npc.y - 62 + Math.sin(t * 4) * 3;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(npc.x, my, 1, npc.x, my, 16);
    g.addColorStop(0, 'rgba(255,220,130,0.5)');
    g.addColorStop(1, 'rgba(255,220,130,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(npc.x, my, 16, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
    label(marker, npc.x, my + 5, '#ffe39a', 17, 800);
  }
}

function drawChest(c) {
  const p = game.p;
  const t = game.time;
  const ready = !c.opened && p.stage === 3 && p.ghostKills >= 6;
  const opened = c.opened;
  shadow(c.x, c.y + 2, 22, 7, 0.35);

  if (ready) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    const g = ctx.createRadialGradient(c.x, c.y - 12, 2, c.x, c.y - 12, 50);
    g.addColorStop(0, `rgba(255,220,130,${0.25 + Math.sin(t * 3) * 0.1})`);
    g.addColorStop(1, 'rgba(255,200,90,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.arc(c.x, c.y - 12, 50, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  }

  ctx.fillStyle = opened ? '#4a3520' : '#6b4a24';
  roundRect(c.x - 20, c.y - 20, 40, 22, 3);
  ctx.fill();
  ctx.fillStyle = opened ? '#5d452b' : '#8a632f';
  roundRect(c.x - 20, c.y - 28, 40, 12, 4);
  ctx.fill();
  if (opened) {
    ctx.save();
    ctx.translate(c.x, c.y - 28);
    ctx.rotate(-0.8);
    ctx.fillStyle = '#6b4f2c';
    roundRect(-20, -10, 40, 12, 4);
    ctx.fill();
    ctx.restore();
  }
  ctx.strokeStyle = ready ? '#ffe39a' : '#3a2a16';
  ctx.lineWidth = 2;
  ctx.strokeRect(c.x - 20, c.y - 20, 40, 22);
  ctx.fillStyle = ready ? '#ffe39a' : '#a8874a';
  ctx.fillRect(c.x - 4, c.y - 24, 8, 10);
  if (!opened && p.stage < 3) {
    ctx.strokeStyle = 'rgba(160,90,90,0.7)';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(c.x - 24, c.y - 6);
    ctx.lineTo(c.x + 24, c.y - 34);
    ctx.moveTo(c.x + 24, c.y - 6);
    ctx.lineTo(c.x - 24, c.y - 34);
    ctx.stroke();
  }
}

function drawPortal(p) {
  const po = p.portal;
  const pstate = game.p;
  const locked = po.needStage && pstate.stage < po.needStage;
  const t = game.time;
  const col = locked ? '#a05a5a' : po.color;

  shadow(po.x, po.y + 6, 46, 12, 0.4);

  /* Arco */
  ctx.strokeStyle = '#4c4652';
  ctx.lineWidth = 11;
  ctx.beginPath();
  ctx.arc(po.x, po.y - 8, 40, Math.PI * 1.02, Math.PI * 1.98);
  ctx.stroke();
  ctx.fillStyle = '#514b58';
  ctx.fillRect(po.x - 46, po.y - 12, 13, 20);
  ctx.fillRect(po.x + 33, po.y - 12, 13, 20);

  /* Vórtice */
  ctx.save();
  ctx.beginPath();
  ctx.arc(po.x, po.y - 26, 33, Math.PI, Math.PI * 2);
  ctx.closePath();
  ctx.clip();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(po.x, po.y - 30, 2, po.x, po.y - 30, 36);
  g.addColorStop(0, col);
  g.addColorStop(0.45, 'rgba(70,90,120,0.5)');
  g.addColorStop(1, 'rgba(10,15,25,0)');
  ctx.globalAlpha = locked ? 0.35 : 0.85;
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(po.x, po.y - 28, 36, 0, Math.PI * 2);
  ctx.fill();
  if (!locked) {
    for (let i = 0; i < 3; i++) {
      const a = t * 1.4 + i * 2.1;
      ctx.strokeStyle = 'rgba(220,245,255,0.35)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.arc(po.x + Math.cos(a) * 6, po.y - 28 + Math.sin(a) * 4, 14 + i * 5, a, a + 1.6);
      ctx.stroke();
    }
  }
  ctx.restore();

  if (locked) {
    ctx.strokeStyle = 'rgba(200,110,110,0.85)';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(po.x - 16, po.y - 12);
    ctx.lineTo(po.x + 16, po.y - 40);
    ctx.moveTo(po.x + 16, po.y - 12);
    ctx.lineTo(po.x - 16, po.y - 40);
    ctx.stroke();
    label('✕', po.x, po.y - 60, '#ff9a9a', 13, 800);
  }

  if (dist(game.p.x, game.p.y, po.x, po.y) < 120) {
    label(po.label, po.x, po.y - 70, locked ? '#ffb0b0' : '#ffe7b0', 10.5, 600, 0.95);
    if (locked) label(po.needStage === 3 ? 'Derrota 5 limos' : 'Recupera el Fragmento', po.x, po.y - 56, '#c99a9a', 9, 500, 0.9);
  }
}

/* ----------------------------- Efectos ----------------------------- */
function drawTelegraph(fx) {
  const pr = 1 - fx.life / fx.max;
  const pulse = 0.5 + Math.sin(game.time * 14) * 0.5;
  ctx.save();
  ctx.globalAlpha = 0.12 + pr * 0.2;
  ctx.fillStyle = fx.color;
  ctx.beginPath();
  ctx.arc(fx.x, fx.y, fx.r, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 0.65 + pulse * 0.25;
  ctx.strokeStyle = fx.color;
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(fx.x, fx.y, fx.r, 0, Math.PI * 2);
  ctx.stroke();
  ctx.globalAlpha = 0.5;
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(fx.x, fx.y, fx.r * (0.35 + pr * 0.6), 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
}

function drawEffects() {
  for (const fx of game.effects) {
    if (fx.kind === 'telegraph') { drawTelegraph(fx); continue; }
    const a = fx.life / fx.max;
    if (fx.kind === 'ring') {
      const r = fx.r * (0.35 + (1 - a) * 0.75);
      ctx.save();
      ctx.globalAlpha = a * 0.85;
      ctx.strokeStyle = fx.color;
      ctx.lineWidth = 3 + a * 4;
      ctx.beginPath();
      ctx.arc(fx.x, fx.y, r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.globalAlpha = a * 0.18;
      ctx.fillStyle = fx.color;
      ctx.beginPath();
      ctx.arc(fx.x, fx.y, r, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    } else if (fx.kind === 'slash') {
      const pr = 1 - a;
      const start = fx.dir - 1.2 + pr * 1.6;
      ctx.save();
      ctx.globalAlpha = a * 0.9;
      ctx.strokeStyle = '#fff4d0';
      ctx.lineWidth = 7 * a + 2;
      ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.arc(fx.x, fx.y - 6, 48, start, start + 1.05);
      ctx.stroke();
      ctx.strokeStyle = bladeColor();
      ctx.globalAlpha = a * 0.55;
      ctx.lineWidth = 13 * a + 3;
      ctx.beginPath();
      ctx.arc(fx.x, fx.y - 6, 46, start, start + 1.05);
      ctx.stroke();
      ctx.restore();
    }
  }
}

function drawParticles() {
  for (const pt of game.particles) {
    ctx.globalAlpha = Math.max(0, pt.life / pt.max);
    ctx.fillStyle = pt.color;
    ctx.beginPath();
    ctx.arc(pt.x, pt.y, pt.size * (0.5 + pt.life / pt.max * 0.5), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

function drawNumbers() {
  for (const n of game.numbers) {
    const a = Math.min(1, n.life / n.max * 1.6);
    ctx.save();
    ctx.globalAlpha = a;
    ctx.font = `800 ${n.crit ? 19 : 14}px Inter, system-ui, sans-serif`;
    ctx.textAlign = 'center';
    ctx.lineWidth = 4;
    ctx.strokeStyle = 'rgba(0,0,0,0.8)';
    ctx.strokeText(n.text, n.x, n.y);
    ctx.fillStyle = n.color;
    ctx.fillText(n.text, n.x, n.y);
    ctx.restore();
  }
}

function drawWeather() {
  const t = game.time;
  for (const w of game.weather) {
    if (!inView(w.x, w.y, 40)) continue;
    if (w.kind === 'embers') {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = 0.35 + Math.sin(w.ph) * 0.2;
      ctx.fillStyle = '#ffb066';
      ctx.beginPath();
      ctx.arc(w.x, w.y, w.s * 0.8, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    } else if (w.kind === 'fireflies') {
      const pulse = 0.25 + Math.max(0, Math.sin(w.ph * 1.4)) * 0.75;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.globalAlpha = pulse * 0.8;
      ctx.fillStyle = '#ffe9a8';
      ctx.beginPath();
      ctx.arc(w.x, w.y, w.s * 0.9, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = pulse * 0.18;
      ctx.beginPath();
      ctx.arc(w.x, w.y, w.s * 4, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    } else {
      ctx.save();
      ctx.translate(w.x, w.y);
      ctx.rotate(w.ph);
      ctx.globalAlpha = 0.55;
      ctx.fillStyle = w.s > 3 ? '#c9a04a' : '#4f7a4a';
      ctx.beginPath();
      ctx.ellipse(0, 0, w.s * 1.6, w.s * 0.7, 0.5, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
  }
}

/* ----------------------------- Objetivo ----------------------------- */
function drawObjectiveMarker(target) {
  if (!target || target.mapId !== game.mapId) return;
  if (!inView(target.x, target.y, 40)) return;
  const t = game.time;
  const y = target.y - 62 + Math.sin(t * 3) * 4;
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const g = ctx.createRadialGradient(target.x, y, 1, target.x, y, 22);
  g.addColorStop(0, 'rgba(255,222,140,0.55)');
  g.addColorStop(1, 'rgba(255,200,90,0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(target.x, y, 22, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.translate(target.x, y);
  ctx.rotate(Math.PI / 4);
  ctx.fillStyle = '#ffe39a';
  ctx.strokeStyle = 'rgba(60,40,10,0.7)';
  ctx.lineWidth = 1.5;
  ctx.fillRect(-5, -5, 10, 10);
  ctx.strokeRect(-5, -5, 10, 10);
  ctx.restore();
}

function drawObjectiveArrow(target) {
  if (!target || target.mapId !== game.mapId || !game.p) return;
  const v = game.view;
  const cam = game.camera;
  const sx = (target.x - cam.x) * v.zoom;
  const sy = (target.y - cam.y) * v.zoom;
  const margin = 46;
  const top = 92;
  if (sx > margin && sx < v.cssW - margin && sy > top && sy < v.cssH - margin) return;

  const cx = v.cssW / 2, cy = v.cssH / 2;
  const ang = Math.atan2(sy - cy, sx - cx);
  const rx = Math.min(cx - margin, Math.abs(Math.cos(ang)) > 0.001 ? Math.abs((sx > cx ? v.cssW - margin - cx : margin - cx) / Math.cos(ang)) : 1e9);
  const ry = Math.min(cy - top, Math.abs(Math.sin(ang)) > 0.001 ? Math.abs((sy > cy ? v.cssH - margin - cy : top - cy) / Math.sin(ang)) : 1e9);
  const rr = Math.min(rx, ry);
  const ax = cx + Math.cos(ang) * rr;
  const ay = cy + Math.sin(ang) * rr;

  const d = Math.round(dist(game.p.x, game.p.y, target.x, target.y) / 22);
  ctx.save();
  ctx.translate(ax, ay);
  ctx.rotate(ang);
  ctx.fillStyle = 'rgba(10,14,22,0.82)';
  ctx.strokeStyle = 'rgba(233,201,119,0.65)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.arc(0, 0, 17, 0, Math.PI * 2);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = '#ffe39a';
  ctx.beginPath();
  ctx.moveTo(12, 0);
  ctx.lineTo(1, -6);
  ctx.lineTo(3, 0);
  ctx.lineTo(1, 6);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  ctx.save();
  ctx.font = '700 10px Inter, system-ui, sans-serif';
  ctx.textAlign = 'center';
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'rgba(0,0,0,0.8)';
  ctx.strokeText(`${d} m`, ax, ay + 30);
  ctx.fillStyle = '#e9c977';
  ctx.fillText(`${d} m`, ax, ay + 30);
  ctx.restore();
}

/* ----------------------------- Frame ----------------------------- */
function render() {
  const v = game.view;
  const dpr = v.dpr;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, v.cssW, v.cssH);
  ctx.fillStyle = '#05070c';
  ctx.fillRect(0, 0, v.cssW, v.cssH);
  if (!game.map || !game.p) return;

  const shake = game.shake;
  const sx = shake > 0.2 ? rand(-1, 1) * shake : 0;
  const sy = shake > 0.2 ? rand(-1, 1) * shake : 0;
  const z = v.zoom * dpr;
  ctx.setTransform(z, 0, 0, z, (-game.camera.x + sx) * z, (-game.camera.y + sy) * z);

  const map = game.map;
  drawGround(map);

  /* Efectos de suelo (telegrafiado del jefe) */
  for (const fx of game.effects) if (fx.kind === 'telegraph') drawTelegraph(fx);

  /* Lista ordenada por profundidad */
  const items = [];
  for (const pr of map.props) {
    if (pr.kind === 'house' || pr.kind === 'portal' || inView(pr.x, pr.y, 140)) {
      items.push({ y: pr.y, kind: 'prop', ref: pr });
    }
  }
  for (const npc of map.npcs) if (inView(npc.x, npc.y)) items.push({ y: npc.y + 2, kind: 'npc', ref: npc });
  for (const e of game.enemies) if (inView(e.x, e.y)) items.push({ y: e.y + e.r, kind: 'enemy', ref: e });
  if (game.boss && !game.boss.dead && inView(game.boss.x, game.boss.y)) {
    items.push({ y: game.boss.y + game.boss.r, kind: 'boss', ref: game.boss });
  }
  if (map.chest) items.push({ y: map.chest.y + 8, kind: 'chest', ref: map.chest });
  if (inView(game.p.x, game.p.y)) items.push({ y: game.p.y + game.p.r, kind: 'player', ref: game.p });

  items.sort((a, b) => a.y - b.y);

  for (const it of items) {
    switch (it.kind) {
      case 'prop': {
        const pr = it.ref;
        switch (pr.kind) {
          case 'tree': drawTree(pr); break;
          case 'rock': drawRock(pr); break;
          case 'bush': drawBush(pr); break;
          case 'house': drawHouse(pr); break;
          case 'fountain': drawFountain(pr); break;
          case 'pillar': drawPillar(pr); break;
          case 'crystal': drawCrystal(pr); break;
          case 'torch': drawTorch(pr); break;
          case 'bones': drawBones(pr); break;
          case 'flower': drawFlower(pr); break;
          case 'shrine': drawShrine(pr); break;
          case 'portal': drawPortal(pr); break;
        }
        break;
      }
      case 'npc': drawNpc(it.ref); break;
      case 'enemy': it.ref.type === 'ghost' ? drawGhost(it.ref) : drawSlime(it.ref); break;
      case 'boss': drawBoss(it.ref); break;
      case 'chest': drawChest(it.ref); break;
      case 'player': drawPlayer(); break;
    }
  }

  drawEffects();
  drawParticles();
  drawNumbers();
  drawWeather();

  const target = questTarget();
  drawObjectiveMarker(target);

  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  if (vignette) {
    ctx.fillStyle = vignette;
    ctx.fillRect(0, 0, v.cssW, v.cssH);
  }

  /* Tinte rojo al recibir daño */
  if (game.p.hitFlash > 0) {
    ctx.fillStyle = `rgba(190,30,30,${game.p.hitFlash * 0.5})`;
    ctx.fillRect(0, 0, v.cssW, v.cssH);
  }

  if (game.scene === 'play' || game.scene === 'travel') drawObjectiveArrow(target);
}

