#stickBase {
  position: absolute;
  left: calc(26px + var(--safe-l));
  bottom: calc(30px + var(--safe-b));
  width: 118px;
  height: 118px;
  border-radius: 50%;
  border: 1.5px solid rgba(233, 201, 119, 0.38);
