  box-shadow: inset 0 0 26px rgba(0, 0, 0, 0.55), 0 6px 20px rgba(0, 0, 0, 0.35);
  opacity: 0.9;
  transition: opacity 0.2s;
}
#stickBase::before,
#stickBase::after {
  content: '';
  position: absolute;
  background: rgba(233, 201, 119, 0.14);
  pointer-events: none;
}
