  const rng = mulberry32(seed);
  let placed = 0, attempts = 0;
  const max = count * 80;
  while (placed < count && attempts < max) {
    attempts++;
    const x = 60 + rng() * (map.w - 120);
    const y = 90 + rng() * (map.h - 160);
    if (avoid.some((a) => dist2(x, y, a.x, a.y) < a.r * a.r)) continue;
